// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 min = c.MinDeposit();
        amount1 = bound(amount1, min + 1, type(uint128).max);
        amount2 = bound(amount2, min + 1, type(uint128).max);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.Deposit{value: amount1}();
        vm.prank(actor);
        c.Deposit{value: amount2}();

        assertEq(c.balances(actor), amount1 + amount2);
    }
}
